def closest_integer(value):
    number = float(value)
    floor_value = int(number // 1)
    ceil_value = floor_value + (1 if number > floor_value else 0)

    if abs(number - floor_value) < 0.5:
        return floor_value
    else:
        return ceil_value if number > 0 else -ceil_value

